/**
 * Creates an iterable yielding Fibonacci numbers up to limit.
 */
function createFibonacciSequence(limit = 100) {
  return {
    *[Symbol.iterator]() {
      let a = 0, b = 1;
      while (a <= limit) {
        yield a;
        const next = a + b;
        a = b;
        b = next;
      }
    }
  };
}
